import json, sys

a = json.load(open(sys.argv[1]))
b = json.load(open(sys.argv[2]))
TOL = 60000  # ms tolerance for TTL (dynamic since capture)

def strip_pttl(d):
    return {k: v for k, v in d.items() if k != 'pttl'}

errs = []
# db-level key set compare
for db in sorted(set(a) | set(b)):
    ka = set(a.get(db, {})); kb = set(b.get(db, {}))
    if ka != kb:
        miss = ka - kb; extra = kb - ka
        if miss: errs.append('DB %s missing keys: %s' % (db, sorted(miss)[:10]))
        if extra: errs.append('DB %s extra keys: %s' % (db, sorted(extra)[:10]))

for db in sorted(set(a) & set(b)):
    for k in a[db]:
        if k not in b[db]: continue
        va, vb = a[db][k], b[db][k]
        sa, sb = strip_pttl(va), strip_pttl(vb)
        if sa != sb:
            # find difference
            if va['type'] != vb['type']:
                errs.append('DB %s key %s: type %s != %s' % (db, k, va['type'], vb['type']))
            elif 'groups' in sa:
                ga = {g['name']: g for g in sa['groups']}
                gb = {g['name']: g for g in sb['groups']}
                if set(ga) != set(gb):
                    errs.append('DB %s stream %s: groups differ %s vs %s' % (db, k, list(ga), list(gb)))
                else:
                    for gname in ga:
                        if ga[gname] != gb[gname]:
                            errs.append('DB %s stream %s group %s: %s vs %s' % (db, k, gname, ga[gname], gb[gname]))
                for f in ('entries','last_id','max_deleted','entries_added','length'):
                    if sa.get(f) != sb.get(f):
                        errs.append('DB %s stream %s field %s differs' % (db, k, f))
            else:
                errs.append('DB %s key %s (%s): value differs' % (db, k, sa['type']))

        # TTL compare
        pa, pb = va.get('pttl'), vb.get('pttl')
        if pa == -1 or pb == -1:
            if pa != pb:
                errs.append('DB %s key %s: ttl persistence %s vs %s' % (db, k, pa, pb))
        else:
            if abs(pa - pb) > TOL:
                errs.append('DB %s key %s: ttl %s vs %s (diff %s)' % (db, k, pa, pb, abs(pa-pb)))

if errs:
    print('MISMATCHES: %d' % len(errs))
    for e in errs[:60]:
        print(' -', e)
    sys.exit(1)
else:
    total = sum(len(v) for v in a.values())
    print('MATCH: all %d keys identical (type+value+streams+groups/PEL; ttl within %d ms)' % (total, TOL))
